  "claim_id": "C034",
  "status": "SUPPORTED",
  "claim": {
    "component_id": "C034",
    "value": "Missing trace spans represent missing evidence, not evidence of zero delay.",
    "scope": "Interpretation of absent phase measurements.",
    "provenance": {
      "refs": [
        {
          "source_id": "P021",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "P021 explicitly states this evidentiary distinction."
    }
  },
  "signal_basis": {
    "component_id": "signal_basis",
    "value": "Phase timing is examined where comparable trace spans exist; an absent span leaves the corresponding phase measurement unavailable.",
    "scope": "Interpreting missing measurements when separating export time into phases.",
    "provenance": {
      "refs": [
        {
          "source_id": "P020",
          "role": "SUPPORT"
        },
        {
          "source_id": "P021",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "P020 bounds phase analysis to comparable spans, and P021 identifies missing spans as missing evidence."
    }
  },
  "stated_empirical_relation": {
    "component_id": "stated_empirical_relation",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
      "refs": [],
      "support_status": "SUFFICIENT",
      "rationale": "The claim is supported without an unresolved empirical relation."
    }
  },
  "rationale": "An absent timing measurement does not establish a measured duration of zero. The claim preserves that distinction without asserting whether delay actually occurred.",
  "uncertainty": "The duration of any unmeasured phase remains unknown; this does not undermine the claim.",
  "anomalies": []
}
